import net.neoforged.neoforge.common.util.FakePlayer;
import com.mojang.authlib.GameProfile;

/** Integration checks only invoked by the opt-in SelfCheck in its disposable world. */
final class CampaignChecks {
 static void ok(boolean b,String m){if(!b)throw new AssertionError("CAMPAIGN: "+m);}
 static FakePlayer player(ServerLevel l,String id){return new FakePlayer(l,new GameProfile(UUID.nameUUIDFromBytes(id.getBytes(java.nio.charset.StandardCharsets.UTF_8)),id));}
 static void run(MinecraftServer s){
  var hub=s.getLevel(Yggdrasil.HUB);var p=player(hub,"CampaignTest");p.setPos(.5,84,150.5);
  ok(Campaign.unlocked(p,4),"Hrimdalr accessible initially");ok(!Campaign.unlocked(p,3)&&!Campaign.unlocked(p,5)&&!Campaign.unlocked(p,6),"later zones locked");
  var wrong=new ItemStack(Content.get("mana_soul_skaldheim"));p.setItemInHand(InteractionHand.MAIN_HAND,wrong);Campaign.waystone(p);ok(!p.entityTags().contains("ygg_unlock_skaldheim")&&wrong.getCount()==1,"out-of-order soul not consumed");
  for(int i=0;i<4;i++){p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Content.get(Campaign.SOULS[i])));Campaign.waystone(p);ok(p.entityTags().contains("ygg_unlock_"+Campaign.ZONES[i+1]),"soul unlock "+i);ok(p.getMainHandItem().isEmpty(),"soul consumed "+i);}
  var other=player(hub,"OtherPlayer");ok(!Campaign.unlocked(other,3),"progression individual");
  p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Content.get(Campaign.SOULS[0])));Campaign.waystone(p);ok(p.getMainHandItem().getCount()==1,"duplicate soul preserved");
  // Portal restoration and repeated overworld returns must preserve the same anchor.
  var ow=s.overworld();var traveler=player(ow,"PortalOwner");BlockPos anchor=new BlockPos(32,200,32);WorldBuilder.platform(ow,anchor.below(),5,Blocks.STONE_BRICKS);WorldBuilder.put(ow,32,200,32,Yggdrasil.INACTIVE.get());
  traveler.setPos(32.5,200,32.5);traveler.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Content.get("engraved_stone"),4));for(int i=0;i<4;i++)Campaign.repair(traveler,anchor);ok(ow.getBlockState(anchor).is(Yggdrasil.INACTIVE.get()),"four stones still need heart");traveler.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Content.get("root_heart")));Campaign.repair(traveler,anchor);ok(ow.getBlockState(anchor).is(Yggdrasil.PORTAL.get()),"heart activates portal");ok(traveler.getMainHandItem().isEmpty(),"heart consumed");Travel.enter(traveler);int count=Travel.state(s).routes.size();
  for(int i=0;i<4;i++){traveler.setPos(.5,84,150.5);Travel.select(traveler,0);ok(traveler.level().dimension().equals(Level.OVERWORLD),"overworld return");Travel.enter(traveler);ok(Travel.state(s).routes.size()==count,"no new return portal records");}
  var bind=Travel.state(s).routes.get("gate:"+traveler.getUUID()+":"+Level.OVERWORLD.identifier());ok(bind.pos().equals(anchor),"original gate remains bound");
  // Dedicated enchanting table payment and realm restrictions.
  var ice=player(s.getLevel(Yggdrasil.realm("hrimdalr")),"RuneTest");ice.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Content.get("hrimsteel_sword")));ice.setItemInHand(InteractionHand.OFF_HAND,new ItemStack(Content.get("hrimsteel_ingot"),3));ice.experienceLevel=30;Campaign.enchant(ice,0);ok(Campaign.enchantLevel(ice,"rime_edge")==1,"dedicated enchant applied");ok(ice.experienceLevel==10&&ice.getOffhandItem().isEmpty(),"enchant payment consumed");Campaign.enchant(ice,0);ok(Campaign.enchantLevel(ice,"rime_edge")==1,"insufficient payment rejected");Campaign.enchant(ice,1);ok(Campaign.enchantLevel(ice,"ember_edge")==0,"wrong realm rejected");
  // Real generated chunks must contain their own ore, not merely register its identifier.
  for(int tier=0;tier<4;tier++){var level=s.getLevel(Yggdrasil.realm(Campaign.ZONES[tier]));int found=0;for(int x=0;x<32;x++)for(int z=0;z<32;z++)for(int y=-56;y<64;y++)if(level.getBlockState(new BlockPos(x,y,z)).is(Content.block(Content.TIERS[tier]+"_ore")))found++;ok(found>0,"ore actually generated "+tier);System.out.println("ORE_GENERATION_PASS "+Content.TIERS[tier]+" blocks="+found);}
  var weatherOverworld=s.overworld().getRainLevel(1);Campaign.weather(new net.neoforged.neoforge.event.tick.LevelTickEvent.Post(()->true,(ServerLevel)ice.level()));ok(s.overworld().getRainLevel(1)==weatherOverworld,"realm weather leaves overworld unchanged");
  WorldBuilder.box((ServerLevel)ice.level(),-5,208,-5,5,212,5,Blocks.AIR);var cold=player((ServerLevel)ice.level(),"ColdTest");cold.setPos(0,210,0);cold.getPersistentData().putFloat("ygg_temperature",36);Campaign.tick(cold);ok(cold.getPersistentData().getFloatOr("ygg_temperature",0)<36,"cold lowers temperature");WorldBuilder.put((ServerLevel)cold.level(),2,210,0,Blocks.CAMPFIRE);Campaign.tick(cold);ok(cold.getPersistentData().getFloatOr("ygg_temperature",0)>36,"nearby campfire warms player");
  var hot=player(s.getLevel(Yggdrasil.realm("solfara")),"DistillTest");BlockPos base=new BlockPos(0,210,0);WorldBuilder.put((ServerLevel)hot.level(),0,210,0,Content.block("condenser"));WorldBuilder.put((ServerLevel)hot.level(),1,210,0,Blocks.PACKED_ICE);hot.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Content.get("heated_flask")));Campaign.interact(hot,base,"condenser");ok(hot.getInventory().countItem(Content.get("purified_flask"))==1,"condensation produces safe water");hot.getPersistentData().putFloat("ygg_temperature",45);var flask=new ItemStack(Content.get("purified_flask"));Campaign.drink(hot,flask);ok(hot.getPersistentData().getFloatOr("ygg_temperature",0)==41&&flask.isEmpty(),"water cools player and is consumed");
  // Every guardian has its proper health and mana drop.
  for(int i=0;i<4;i++){var l=s.getLevel(Yggdrasil.realm(Campaign.ZONES[i]));l.getChunk(5,5);var member=player(l,"GuardianLoot"+i);member.setPos(82,210,80);l.addNewPlayer(member);var boss=Actors.GUARDIANS.get(i).get().create(l,EntitySpawnReason.TRIGGERED);ok(boss!=null,"boss type created");boss.configure(i);ok(boss.getMaxHealth()==300+i*200,"tier boss health "+i);boss.setPos(80,210,80);l.addFreshEntity(boss);boss.die(member.damageSources().playerAttack(member));ok(member.getInventory().countItem(Content.get(Campaign.SOULS[i]))==1,"boss awards correct personal soul "+i);boss.discard();l.removePlayerImmediately(member,net.minecraft.world.entity.Entity.RemovalReason.DISCARDED);}

  var groupLevel=s.getLevel(Yggdrasil.realm("hrimdalr"));var memberA=player(groupLevel,"GroupA");var memberB=player(groupLevel,"GroupB");memberA.setPos(500,210,500);memberB.setPos(504,210,500);groupLevel.getChunk(31,31);groupLevel.addNewPlayer(memberA);groupLevel.addNewPlayer(memberB);
  var groupBoss=Actors.GUARDIANS.get(0).get().create(groupLevel,EntitySpawnReason.TRIGGERED);groupBoss.configure(0);groupBoss.setPos(500,210,500);groupLevel.addFreshEntity(groupBoss);groupBoss.die(memberA.damageSources().playerAttack(memberA));groupBoss.discard();ok(memberA.getInventory().countItem(Content.get(Campaign.SOULS[0]))==1&&memberB.getInventory().countItem(Content.get(Campaign.SOULS[0]))==1,"both nearby players receive a personal mana soul");
  ok(Actors.summonBoss(memberA,new BlockPos(500,210,500),0),"guardian can be resummoned after death");for(var b:groupLevel.getEntitiesOfClass(Actors.RealmBoss.class,memberA.getBoundingBox().inflate(30)))b.discard();
  WorldBuilder.box(groupLevel,470,209,470,530,209,530,Blocks.PACKED_ICE);var prey=Actors.spawnSpecter(memberA,0);ok(prey!=null&&prey.entityTags().contains("ygg_realm_creature"),"realm creature successfully registered on suitable terrain");
  int stones=memberA.getInventory().countItem(Content.get("engraved_stone"));Campaign.killed(new net.neoforged.neoforge.event.entity.living.LivingDeathEvent(prey,memberA.damageSources().playerAttack(memberA)));ok(memberA.getInventory().countItem(Content.get("engraved_stone"))==stones+1,"realm kill supplies offering ingredient");prey.discard();
  ok(Campaign.storm(groupLevel),"Hrimdalr permanent blizzard");groupLevel.removePlayerImmediately(memberA,net.minecraft.world.entity.Entity.RemovalReason.DISCARDED);groupLevel.removePlayerImmediately(memberB,net.minecraft.world.entity.Entity.RemovalReason.DISCARDED);
  System.out.println("PATCH2_SELFTEST_PASS multiplayer souls, boss resummon, creature spawn, offering loot, constant blizzard");
  CampaignWorld.hub(hub);p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);Campaign.commission(p);ok(!p.entityTags().contains("ygg_builder_reward"),"empty plots do not grant reward");
  for(int k=0;k<3;k++){int z=120+k*27;WorldBuilder.box(hub,79,83,z-5,89,83,z+5,Blocks.SPRUCE_PLANKS);WorldBuilder.box(hub,79,90,z-5,89,90,z+5,Blocks.SPRUCE_PLANKS);for(int x:new int[]{79,89})for(int dz:new int[]{-5,5})WorldBuilder.box(hub,x,84,z+dz,x,89,z+dz,Blocks.SPRUCE_LOG);WorldBuilder.bed(hub,83,84,z);for(int dx:new int[]{-3,0,3})WorldBuilder.put(hub,84+dx,85,z+4,Blocks.LANTERN);}
  Campaign.commission(p);ok(p.entityTags().contains("ygg_builder_reward"),"building commission recognized");int bonds=p.getInventory().countItem(Content.get("drake_bond"));Campaign.commission(p);ok(p.getInventory().countItem(Content.get("drake_bond"))==bonds&&bonds==1,"unique building reward");
  Actors.summonDrake(p);Actors.summonDrake(p);int drakes=0;Actors.Drake own=null;for(var l:s.getAllLevels())for(var e:l.getAllEntities())if(e instanceof Actors.Drake d&&d.owner.equals(p.getUUID().toString())){drakes++;own=d;}ok(drakes==1&&own!=null,"single owned drake after recall");p.setShiftKeyDown(true);own.mobInteract(p,InteractionHand.MAIN_HAND);ok(own.waiting,"drake wait order");p.setShiftKeyDown(false);
  var rider=new ServerPlayer(s,hub,new GameProfile(UUID.nameUUIDFromBytes("RealMountTest".getBytes()),"RealMountTest"),net.minecraft.server.level.ClientInformation.createDefault());
  rider.connection=new net.minecraft.server.network.ServerGamePacketListenerImpl(s,new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND),rider,net.minecraft.server.network.CommonListenerCookie.createInitial(rider.getGameProfile(),false)){@Override public void send(net.minecraft.network.protocol.Packet<?> packet){}};
  own.owner=rider.getUUID().toString();own.mobInteract(rider,InteractionHand.MAIN_HAND);ok(own.getControllingPassenger()==rider,"owner can mount with real ServerPlayer");own.control(rider,5,-5,true);ok(own.forward==1&&own.strafe==-1,"flight input bounded");var beforeFlight=own.position();own.tick();ok(own.position().distanceToSqr(beforeFlight)>.05,"server flight moves drake");rider.stopRiding();var waitPos=own.position();own.tick();ok(own.position().distanceToSqr(waitPos)<.001,"wait order holds position");own.owner=p.getUUID().toString();
  var secret=s.getLevel(Yggdrasil.realm("sanctum"));ok(secret!=null,"secret dimension registered");
  var draug=s.getLevel(Yggdrasil.realm("draugavik"));var dungeon=Travel.state(s).routes.get("built:zone_3");ok(dungeon!=null,"dedicated dungeon built");
  Travel.teleport(p,draug,dungeon.pos().offset(0,0,16));p.setPos(dungeon.x+.5,dungeon.y,dungeon.z+16.5);CampaignWorld.secret(p);ok(p.level().dimension().equals(Yggdrasil.realm("sanctum")),"dungeon portal reaches secret arena");ok(secret.getBlockState(new BlockPos(0,83,0)).is(Content.block("boss_altar")),"final arena altar built");
  var finalBoss=Actors.BOSS.get().create(secret,EntitySpawnReason.TRIGGERED);finalBoss.configure(4);finalBoss.setPos(0,83,0);secret.addFreshEntity(finalBoss);p.setPos(0,83,20);finalBoss.die(p.damageSources().playerAttack(p));finalBoss.discard();ok(p.entityTags().contains("ygg_final_victory")&&p.getInventory().countItem(Content.get("world_relic"))==1,"ultimate boss grants relic");ok(p.level().dimension().equals(Yggdrasil.realm("draugavik")),"victory returns to original dungeon");
  int weapons=0;for(String n:new String[]{"valkyrie_blade","abyssal_blade","storm_hammer"})weapons+=p.getInventory().countItem(Content.get(n));ok(weapons==1,"one random ultimate weapon");
  Travel.enter(p);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Content.get("world_relic")));Campaign.waystone(p);ok(p.isSpectator(),"relic starts cinematic");Campaign.tick(p);Campaign.feedback(p,0);ok(!p.isSpectator()&&p.level().dimension().equals(Level.OVERWORLD),"ending restores game mode and returns overworld");ok(p.entityTags().contains("ygg_story_finished"),"ending persisted");ok(Travel.state(s).feedback.get(p.getUUID().toString())==0,"feedback stored locally");
  System.out.println("CAMPAIGN_SELFTEST_PASS: mana progression, original gate reuse, rune payments, distillation, boss drops, building reward, owned drake.");
 }
}
